# 1. List the number of films per category.
SELECT
	c.name, 
    COUNT(f.film_id) AS 'n_films'
FROM 
	category AS c
JOIN 
	film_category AS f
ON 
	
		c.category_id = f.category_id
GROUP BY c.name;

# 2. Retrieve the store ID, city, and country for each store.
SELECT
	s.store_id, ci.city, co.country
FROM 
	store AS s
JOIN
	address AS a
ON
	s.address_id = a.address_id
JOIN
	city AS ci
ON
	a.city_id = ci.city_id
JOIN
	country AS co
ON
	ci.country_id = co.country_id;

# 3. Calculate the total revenue generated by each store in dollars
SELECT
	c.store_id, SUM(p.amount) AS 'total_revenue'
FROM
	payment AS p
JOIN
	rental AS r
ON
	p.rental_id = r.rental_id
JOIN
	customer AS c
ON
	r.customer_id = c.customer_id
JOIN
	store AS s
ON 
	c.store_id = s.store_id
GROUP BY
	s.store_id;
    
# 4. Determine the average running time of films for each category
SELECT 
	c.name AS 'category',
    ROUND(AVG(f.length),2) AS 'avg_run_time'
FROM
	film AS f
JOIN
	film_category AS fc
ON 
	f.film_id = fc.film_id
JOIN
	category as c
ON
	fc.category_id = c.category_id
GROUP BY 
	c.name;
    
# Bonus 5. Identify the film categories with the longest average running time
SELECT 
	c.name AS 'category',
    ROUND(AVG(f.length),2) AS 'avg_run_time'
FROM
	film AS f
JOIN
	film_category AS fc
ON 
	f.film_id = fc.film_id
JOIN
	category as c
ON
	fc.category_id = c.category_id
GROUP BY 
	c.name
ORDER BY
	avg_run_time DESC
LIMIT 3; #I choose to select the top 3 categories.

#Bonus 6. Display the top 10 most frequently rented movies in descending order
SELECT
	f.title AS 'movie',
    COUNT(r.rental_id) AS 'total_rents'
FROM
	film as f
JOIN
	inventory as i
ON
	f.film_id = i.film_id
JOIN
	rental as r
ON
	i.inventory_id = r.inventory_id
GROUP BY 
	movie
ORDER BY
	total_rents DESC
LIMIT 10;

# Bonus 7. Determine if "Academy Dinosaur" can be rented from Store 1.
SELECT
	f.title AS 'movie',
    s.store_id AS 'store'
FROM
	film AS f
JOIN
	inventory AS i
ON 
	f.film_id = i.film_id
JOIN
	store AS s
ON 
	i.store_id = s.store_id
WHERE
	f.title = 'Academy Dinosaur' AND s.store_id = 1;

# Bonus 8. Provide a list of all distinct film titles, along with their availability status in the inventory.
#Include a column indicating whether each title is 'Available' or 'NOT available.
# there are 42 titles that are not in the inventory, and this information can be obtained using a CASE statement combined with IFNULL.
SELECT
	DISTINCT(f.title) AS 'film',
    CASE
		WHEN ISNULL(i.film_id) THEN 'Not Available'
        ELSE 'Available'
	END AS 'availability'
FROM
	film AS f
LEFT JOIN
	inventory as i
ON
	f.film_id = i.film_id

	
	